  localparam PTR_WIDTH = $clog2(DEPTH); // address bits? For DEPTH=8, 3.
  localparam PTR_BITS = PTR_WIDTH + 1;

  reg [WIDTH-1:0] mem [0:DEPTH-1];

  reg [PTR_BITS-1:0] wptr_bin, rptr_bin;
  reg [PTR_BITS-1:0] wptr_gray, rptr_gray;
  reg [PTR_BITS-1:0] wptr_gray_sync1, wptr_gray_sync2;
  reg [PTR_BITS-1:0] rptr_gray_sync1, rptr_gray_sync2;
  wire [PTR_BITS-1:0] wptr_bin_next, rptr_bin_next;
  wire [PTR_BITS-1:0] wptr_gray_next, rptr_gray_next;
  wire [PTR_BITS-1:0] wptr_bin_sync, rptr_bin_sync? Not needed.

  assign wptr_bin_next = wptr_bin + (winc & ~wfull);
  assign wptr_gray_next = wptr_bin_next ^ (wptr_bin_next >> 1);
  assign rptr_bin_next = rptr_bin + (rinc & ~rempty);
  assign rptr_gray_next = rptr_bin_next ^ (rptr_bin_next >> 1);

  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0; wptr_gray <= 0;
      wptr_gray_sync1 <= 0; wptr_gray_sync2 <= 0;
